variables.input:
fetch events, bucket:{"default_network_flows"}
| summarize count(), by:{host.name}
| fields host.name
| sort host.name asc

10.query:
fetch events, bucket:{"default_network_flows"}
| filter in(host.name, array($Host))
| summarize total_flows = count()

11.query:
fetch events, bucket:{"default_network_flows"}
| filter in(host.name, array($Host))
| summarize bytes_rx = sum(network_flow.bytes.rx)

12.query:
fetch events, bucket:{"default_network_flows"}
| filter in(host.name, array($Host))
| summarize bytes_tx = sum(network_flow.bytes.tx)

13.query:
fetch events, bucket:{"default_network_flows"}
| filter in(host.name, array($Host))
| summarize new_sessions = sum(network_flow.tcp.sessions.new)

21.query:
fetch events, bucket:{"default_network_flows"}
| filter in(host.name, array($Host))
| makeTimeseries bytes_rx = sum(network_flow.bytes.rx), bytes_tx = sum(network_flow.bytes.tx), interval: 5m

22.query:
fetch events, bucket:{"default_network_flows"}
| filter in(host.name, array($Host))
| makeTimeseries new_sessions = sum(network_flow.tcp.sessions.new), interval: 5m

23.query:
fetch events, bucket:{"default_network_flows"}
| filter in(host.name, array($Host))
| summarize bytes = sum(network_flow.bytes.rx) + sum(network_flow.bytes.tx), by: {network_flow.source.address}
| sort bytes desc
| limit 10

24.query:
fetch events, bucket:{"default_network_flows"}
| filter in(host.name, array($Host))
| summarize bytes = sum(network_flow.bytes.rx) + sum(network_flow.bytes.tx), by: {network_flow.destination.address}
| sort bytes desc
| limit 10

52.query:
fetch events, bucket:{"default_network_flows"}
| filter in(host.name, array($Host))
| summarize tcp_errors = sum(network_flow.tcp.sessions.reset) + sum(network_flow.tcp.sessions.timeout)

53.query:
fetch events, bucket:{"default_network_flows"}
| filter in(host.name, array($Host))
| summarize retrans = sum(network_flow.packets.retransmitted.rx) + sum(network_flow.packets.retransmitted.tx)

55.query:
fetch events, bucket:{"default_network_flows"}
| filter in(host.name, array($Host))

| summarize count = count(), by:{network_flow.source.address, network_flow.destination.address}
